#[derive(Clone, Copy, Debug)]
pub struct Hsl {
    pub hue: f32,
    pub saturation: f32,
    pub lightness: f32,
}

impl Hsl {
    pub const fn new(hue: f32, saturation: f32, lightness: f32) -> Self {
        Self {
            hue,
            saturation,
            lightness,
        }
    }
}

pub struct ColorConverter;

impl ColorConverter {
    pub fn hue_difference(left: Hsl, right: Hsl) -> f32 {
        let _ = (left.saturation, left.lightness, right.saturation, right.lightness);

        let mut difference = (left.hue - right.hue).abs();
        if difference > 180.0_f32 {
            difference = 360.0_f32 - difference;
        }
        difference
    }
}

