const DEFAULT_PRECISION: usize = 6;

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return String::from("nan");
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0_f32 {
        return String::from("0");
    }

    let scientific = format!("{:.*e}", DEFAULT_PRECISION - 1, value);
    let (mantissa, exponent) = scientific
        .split_once('e')
        .expect("scientific float formatting always contains an exponent");
    let exponent = exponent
        .parse::<i32>()
        .expect("rust scientific exponent should be a valid integer");

    if exponent < -4 || exponent >= DEFAULT_PRECISION as i32 {
        let trimmed = trim_fraction(mantissa);
        format!("{trimmed}e{}", format_exponent(exponent))
    } else {
        let decimals = (DEFAULT_PRECISION as i32 - (exponent + 1)) as usize;
        trim_fraction(&format!("{:.*}", decimals, value))
    }
}

fn trim_fraction(number: &str) -> String {
    if !number.contains('.') {
        return number.to_owned();
    }

    let trimmed = number.trim_end_matches('0').trim_end_matches('.');
    if trimmed == "-0" {
        String::from("0")
    } else {
        trimmed.to_owned()
    }
}

fn format_exponent(exponent: i32) -> String {
    let sign = if exponent < 0 { '-' } else { '+' };
    let absolute = exponent.unsigned_abs();
    if absolute < 10 {
        format!("{sign}0{absolute}")
    } else {
        format!("{sign}{absolute}")
    }
}
